import pandas as pd
import re
from datetime import datetime

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw_payments = inputs["raw_payments"].copy()

    # Initialize reject tracking
    rejects = []
    valid_indices = []

    # Rule evaluation for each row
    for idx, row in raw_payments.iterrows():
        row_num = row["row_num"]
        reject_reason = None

        # R1: MISSING_ID
        payment_id = row["payment_id"]
        if pd.isna(payment_id) or (isinstance(payment_id, str) and payment_id.strip() == ""):
            reject_reason = "MISSING_ID"

        # R2: BAD_AMOUNT
        if reject_reason is None:
            amount_txt = row["amount_txt"]
            if pd.isna(amount_txt):
                reject_reason = "BAD_AMOUNT"
            else:
                amount_txt_trimmed = str(amount_txt).strip()
                # Legacy number pattern: optional +/-, one or more digits, optional .DD
                if not re.match(r'^[+\-]?\d+(\.\d{1,2})?$', amount_txt_trimmed):
                    reject_reason = "BAD_AMOUNT"

        # R3: NON_POSITIVE
        if reject_reason is None:
            try:
                amount = float(str(row["amount_txt"]).strip())
                if amount <= 0:
                    reject_reason = "NON_POSITIVE"
            except:
                reject_reason = "BAD_AMOUNT"

        # R4: BAD_CURRENCY
        if reject_reason is None:
            currency = row["currency"]
            if pd.isna(currency):
                reject_reason = "BAD_CURRENCY"
            else:
                currency_upper = str(currency).strip().upper()
                if currency_upper not in ["USD", "EUR", "GBP"]:
                    reject_reason = "BAD_CURRENCY"

        # R5: BAD_DATE
        if reject_reason is None:
            pay_date_txt = row["pay_date_txt"]
            if pd.isna(pay_date_txt):
                reject_reason = "BAD_DATE"
            else:
                pay_date_txt_trimmed = str(pay_date_txt).strip()
                # Must be exactly YYYY-MM-DD format
                if not re.match(r'^\d{4}-\d{2}-\d{2}$', pay_date_txt_trimmed):
                    reject_reason = "BAD_DATE"
                else:
                    # Validate it's a real calendar date
                    try:
                        datetime.strptime(pay_date_txt_trimmed, "%Y-%m-%d")
                    except ValueError:
                        reject_reason = "BAD_DATE"

        if reject_reason is not None:
            rejects.append({"row_num": row_num, "reject_reason": reject_reason})
        else:
            valid_indices.append(idx)

    # R6: DUPLICATE - among rows that passed R1-R5
    valid_rows = raw_payments.loc[valid_indices].copy()

    # Track which rows to keep (lowest row_num per trimmed payment_id)
    if len(valid_rows) > 0:
        valid_rows["trimmed_payment_id"] = valid_rows["payment_id"].str.strip()

        # Group by trimmed_payment_id and find the min row_num in each group
        min_row_per_id = valid_rows.groupby("trimmed_payment_id", sort=False)["row_num"].min()

        # Rows to keep are those with row_num == min for their group
        rows_to_keep_mask = valid_rows["row_num"].isin(min_row_per_id.values)
        duplicate_rejects = valid_rows[~rows_to_keep_mask]

        # Add duplicates to rejects
        for _, row in duplicate_rejects.iterrows():
            rejects.append({"row_num": row["row_num"], "reject_reason": "DUPLICATE"})

        # Keep only non-duplicate valid rows
        valid_rows = valid_rows[rows_to_keep_mask].copy()

    # Build valid_payments output
    if len(valid_rows) > 0:
        valid_payments = pd.DataFrame({
            "payment_id": valid_rows["payment_id"].str.strip(),
            "account_id": valid_rows["account_id"],
            "amount": valid_rows["amount_txt"].str.strip().astype(float),
            "currency": valid_rows["currency"].str.strip().str.upper(),
            "pay_date": valid_rows["pay_date_txt"].str.strip()
        })
    else:
        valid_payments = pd.DataFrame({
            "payment_id": pd.Series(dtype="object"),
            "account_id": pd.Series(dtype="int64"),
            "amount": pd.Series(dtype="float64"),
            "currency": pd.Series(dtype="object"),
            "pay_date": pd.Series(dtype="object")
        })

    # Build payment_rejects output
    if len(rejects) > 0:
        payment_rejects = pd.DataFrame(rejects)
    else:
        payment_rejects = pd.DataFrame({
            "row_num": pd.Series(dtype="int64"),
            "reject_reason": pd.Series(dtype="object")
        })

    return {
        "valid_payments": valid_payments,
        "payment_rejects": payment_rejects
    }
